-- ConnectionCyber — M09: serviços, oficinas, agenda, ordens de serviço e garantias.
begin;

create table public.erp_assets(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,party_id uuid,code text not null,name text not null,kind text not null default 'other' check(kind in('vehicle','machine','equipment','device','other')),brand text,model text,serial_number text,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tenant_id,code),unique(tenant_id,id),foreign key(tenant_id,party_id) references public.erp_parties(tenant_id,id) on delete restrict);
create table public.erp_asset_identifiers(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,asset_id uuid not null,kind text not null check(kind in('serial','patrimony','vin','plate','imei','other')),value_normalized text not null,created_at timestamptz not null default now(),unique(tenant_id,kind,value_normalized),unique(tenant_id,id),foreign key(tenant_id,asset_id) references public.erp_assets(tenant_id,id) on delete cascade);
create table public.erp_asset_meter_readings(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,asset_id uuid not null,meter_kind text not null check(meter_kind in('odometer_km','hours','cycles','other')),reading numeric(19,4) not null check(reading>=0),read_at timestamptz not null default now(),source_type text,source_id uuid,created_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(tenant_id,asset_id,meter_kind,read_at),unique(tenant_id,id),foreign key(tenant_id,asset_id) references public.erp_assets(tenant_id,id) on delete restrict);
create table public.erp_vehicles(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,asset_id uuid not null,plate_normalized text,vin_normalized text,year_model integer check(year_model between 1886 and 2200),color text,fuel_type text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tenant_id,asset_id),unique nulls not distinct(tenant_id,plate_normalized),unique nulls not distinct(tenant_id,vin_normalized),unique(tenant_id,id),foreign key(tenant_id,asset_id) references public.erp_assets(tenant_id,id) on delete cascade);
create table public.erp_appointments(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,establishment_id uuid not null,party_id uuid,asset_id uuid,code text not null,status text not null default 'scheduled' check(status in('scheduled','confirmed','checked_in','completed','no_show','cancelled')),starts_at timestamptz not null,ends_at timestamptz not null,notes text,idempotency_key text not null,created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tenant_id,code),unique(tenant_id,idempotency_key),unique(tenant_id,id),foreign key(tenant_id,establishment_id) references public.erp_establishments(tenant_id,id) on delete restrict,foreign key(tenant_id,party_id) references public.erp_parties(tenant_id,id) on delete restrict,foreign key(tenant_id,asset_id) references public.erp_assets(tenant_id,id) on delete restrict,check(ends_at>starts_at));
create table public.erp_appointment_resources(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,appointment_id uuid not null,resource_type text not null check(resource_type in('technician','bay','equipment')),resource_key text not null,created_at timestamptz not null default now(),unique(tenant_id,appointment_id,resource_type,resource_key),unique(tenant_id,id),foreign key(tenant_id,appointment_id) references public.erp_appointments(tenant_id,id) on delete cascade);
create table public.erp_service_orders(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,establishment_id uuid not null,party_id uuid not null,asset_id uuid,appointment_id uuid,sale_id uuid,code text not null,status text not null default 'draft' check(status in('draft','diagnosis','awaiting_approval','approved','in_progress','paused','ready','completed','cancelled')),priority text not null default 'normal' check(priority in('low','normal','high','urgent')),complaint text,diagnosis text,subtotal numeric(19,4) not null default 0 check(subtotal>=0),discount_total numeric(19,4) not null default 0 check(discount_total>=0),grand_total numeric(19,4) not null default 0 check(grand_total>=0),idempotency_key text not null,opened_at timestamptz not null default now(),completed_at timestamptz,created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tenant_id,code),unique(tenant_id,idempotency_key),unique nulls not distinct(tenant_id,sale_id),unique(tenant_id,id),foreign key(tenant_id,establishment_id) references public.erp_establishments(tenant_id,id) on delete restrict,foreign key(tenant_id,party_id) references public.erp_parties(tenant_id,id) on delete restrict,foreign key(tenant_id,asset_id) references public.erp_assets(tenant_id,id) on delete restrict,foreign key(tenant_id,appointment_id) references public.erp_appointments(tenant_id,id) on delete restrict,foreign key(tenant_id,sale_id) references public.erp_sales(tenant_id,id) on delete restrict,check((status='completed' and completed_at is not null and sale_id is not null) or status<>'completed'));
create table public.erp_service_order_items(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,service_order_id uuid not null,item_id uuid not null,variant_id uuid,unit_id uuid not null,stock_location_id uuid,item_kind text not null check(item_kind in('labor','part','material','fee')),description_snapshot text not null,quantity numeric(19,6) not null check(quantity>0),unit_price numeric(19,4) not null check(unit_price>=0),discount_total numeric(19,4) not null default 0 check(discount_total>=0),line_total numeric(19,4) not null check(line_total>=0),approval_required boolean not null default true,created_at timestamptz not null default now(),unique(tenant_id,id),foreign key(tenant_id,service_order_id) references public.erp_service_orders(tenant_id,id) on delete cascade,foreign key(tenant_id,item_id) references public.erp_catalog_items(tenant_id,id) on delete restrict,foreign key(tenant_id,item_id,variant_id) references public.erp_item_variants(tenant_id,item_id,id) on delete restrict,foreign key(tenant_id,unit_id) references public.erp_units(tenant_id,id) on delete restrict,foreign key(tenant_id,stock_location_id) references public.erp_stock_locations(tenant_id,id) on delete restrict,check(line_total=quantity*unit_price-discount_total));
create table public.erp_service_order_events(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,service_order_id uuid not null,event_type text not null,from_status text,to_status text,notes text,idempotency_key text not null,created_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(tenant_id,idempotency_key),unique(tenant_id,id),foreign key(tenant_id,service_order_id) references public.erp_service_orders(tenant_id,id) on delete restrict);
create table public.erp_service_assignments(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,service_order_id uuid not null,technician_id uuid not null references auth.users(id),role text not null default 'technician',assigned_at timestamptz not null default now(),released_at timestamptz,unique(tenant_id,service_order_id,technician_id,role),unique(tenant_id,id),foreign key(tenant_id,service_order_id) references public.erp_service_orders(tenant_id,id) on delete cascade,check(released_at is null or released_at>=assigned_at));
create table public.erp_work_logs(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,service_order_id uuid not null,technician_id uuid not null references auth.users(id),started_at timestamptz not null,ended_at timestamptz,notes text,idempotency_key text not null,created_at timestamptz not null default now(),unique(tenant_id,idempotency_key),unique(tenant_id,id),foreign key(tenant_id,service_order_id) references public.erp_service_orders(tenant_id,id) on delete restrict,check(ended_at is null or ended_at>started_at));
create table public.erp_inspections(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,service_order_id uuid not null,kind text not null check(kind in('check_in','diagnostic','quality','delivery')),status text not null default 'draft' check(status in('draft','completed','cancelled')),completed_at timestamptz,created_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(tenant_id,service_order_id,kind),unique(tenant_id,id),foreign key(tenant_id,service_order_id) references public.erp_service_orders(tenant_id,id) on delete cascade);
create table public.erp_inspection_items(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,inspection_id uuid not null,code text not null,label text not null,result text not null check(result in('ok','attention','critical','not_applicable')),notes text,created_at timestamptz not null default now(),unique(tenant_id,inspection_id,code),unique(tenant_id,id),foreign key(tenant_id,inspection_id) references public.erp_inspections(tenant_id,id) on delete cascade);
create table public.erp_service_attachments(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,service_order_id uuid not null,kind text not null check(kind in('photo','document','signature','other')),storage_bucket text not null,storage_path text not null,content_hash text check(content_hash is null or content_hash~'^[a-f0-9]{64}$'),created_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(tenant_id,storage_bucket,storage_path),unique(tenant_id,id),foreign key(tenant_id,service_order_id) references public.erp_service_orders(tenant_id,id) on delete cascade,check(storage_path not like '%..%'));
create table public.erp_service_approvals(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,service_order_id uuid not null,status text not null check(status in('pending','approved','rejected','revoked')),channel text not null check(channel in('in_person','email','whatsapp','portal','other')),approved_amount numeric(19,4) check(approved_amount is null or approved_amount>=0),evidence_reference text,decided_at timestamptz,idempotency_key text not null,created_at timestamptz not null default now(),unique(tenant_id,idempotency_key),unique(tenant_id,id),foreign key(tenant_id,service_order_id) references public.erp_service_orders(tenant_id,id) on delete restrict,check((status in('approved','rejected','revoked') and decided_at is not null) or status='pending'));
create table public.erp_service_warranties(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,service_order_id uuid not null,starts_on date not null,ends_on date not null,terms text not null,status text not null default 'active' check(status in('active','expired','voided')),created_at timestamptz not null default now(),unique(tenant_id,service_order_id),unique(tenant_id,id),foreign key(tenant_id,service_order_id) references public.erp_service_orders(tenant_id,id) on delete restrict,check(ends_on>=starts_on));
create table public.erp_warranty_events(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,warranty_id uuid not null,event_type text not null check(event_type in('claim','inspection','repair','denial','closure')),notes text,idempotency_key text not null,created_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(tenant_id,idempotency_key),unique(tenant_id,id),foreign key(tenant_id,warranty_id) references public.erp_service_warranties(tenant_id,id) on delete restrict);

insert into public.erp_permissions(key,name,description,category) values ('services.read','Consultar serviços','Consulta agenda, ativos e ordens de serviço.','Serviços'),('services.manage','Gerenciar serviços','Mantém ativos, agenda e ordens de serviço.','Serviços'),('services.diagnose','Diagnosticar serviços','Registra inspeção e diagnóstico.','Serviços'),('services.approve','Registrar aprovações','Registra autorização comprovável do cliente.','Serviços'),('services.execute','Executar serviços','Registra execução, tempo e consumo.','Serviços'),('services.complete','Concluir serviços','Converte OS concluída em venda M07.','Serviços'),('services.warranty','Gerenciar garantias','Registra garantias e retornos.','Serviços') on conflict(key) do update set name=excluded.name,description=excluded.description,category=excluded.category,active=true;

create or replace function public.erp_schedule_appointment(p_tenant_id uuid,p_establishment_id uuid,p_party_id uuid,p_asset_id uuid,p_code text,p_starts_at timestamptz,p_ends_at timestamptz,p_resource_type text,p_resource_key text,p_idempotency_key text) returns uuid language plpgsql security definer set search_path='' as $$ declare v_id uuid;begin if not(erp_security.has_permission(p_tenant_id,'services.manage') or public.is_platform_staff())then raise exception 'permission denied';end if;select id into v_id from public.erp_appointments where tenant_id=p_tenant_id and idempotency_key=p_idempotency_key;if v_id is not null then return v_id;end if;if p_ends_at<=p_starts_at then raise exception 'invalid interval';end if;perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':'||p_resource_type||':'||p_resource_key,0));if exists(select 1 from public.erp_appointment_resources r join public.erp_appointments a on a.tenant_id=r.tenant_id and a.id=r.appointment_id where r.tenant_id=p_tenant_id and r.resource_type=p_resource_type and r.resource_key=p_resource_key and a.status not in('cancelled','no_show') and tstzrange(a.starts_at,a.ends_at,'[)')&&tstzrange(p_starts_at,p_ends_at,'[)'))then raise exception 'resource unavailable';end if;insert into public.erp_appointments(tenant_id,establishment_id,party_id,asset_id,code,starts_at,ends_at,idempotency_key,created_by)values(p_tenant_id,p_establishment_id,p_party_id,p_asset_id,p_code,p_starts_at,p_ends_at,p_idempotency_key,auth.uid())returning id into v_id;insert into public.erp_appointment_resources(tenant_id,appointment_id,resource_type,resource_key)values(p_tenant_id,v_id,p_resource_type,p_resource_key);return v_id;end$$;
create or replace function public.erp_complete_service_order(p_tenant_id uuid,p_service_order_id uuid,p_idempotency_key text) returns uuid language plpgsql security definer set search_path='' as $$ declare v_os public.erp_service_orders%rowtype;v_sale uuid;v_sub numeric(19,4);v_disc numeric(19,4);v_total numeric(19,4);begin if not(erp_security.has_permission(p_tenant_id,'services.complete') or public.is_platform_staff())then raise exception 'permission denied';end if;perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':'||p_service_order_id::text,0));select * into v_os from public.erp_service_orders where tenant_id=p_tenant_id and id=p_service_order_id for update;if not found then raise exception 'service order not found';end if;if v_os.status='completed' then return v_os.sale_id;end if;if v_os.status<>'ready' or v_os.idempotency_key<>p_idempotency_key then raise exception 'service order not ready or idempotency mismatch';end if;if exists(select 1 from public.erp_service_order_items where tenant_id=p_tenant_id and service_order_id=v_os.id and approval_required)and not exists(select 1 from public.erp_service_approvals where tenant_id=p_tenant_id and service_order_id=v_os.id and status='approved')then raise exception 'customer approval required';end if;select coalesce(sum(quantity*unit_price),0),coalesce(sum(discount_total),0),coalesce(sum(line_total),0)into v_sub,v_disc,v_total from public.erp_service_order_items where tenant_id=p_tenant_id and service_order_id=v_os.id;if v_total<=0 or v_total<>v_sub-v_disc then raise exception 'invalid totals';end if;select id into v_sale from public.erp_sales where tenant_id=p_tenant_id and idempotency_key=p_idempotency_key||':sale';if v_sale is null then insert into public.erp_sales(tenant_id,establishment_id,customer_id,code,status,subtotal,discount_total,grand_total,idempotency_key,created_by)values(p_tenant_id,v_os.establishment_id,v_os.party_id,v_os.code||'-VENDA','draft',v_sub,v_disc,v_total,p_idempotency_key||':sale',auth.uid())returning id into v_sale;insert into public.erp_sale_items(tenant_id,sale_id,item_id,variant_id,unit_id,stock_location_id,item_code_snapshot,description_snapshot,quantity,unit_price,discount_total,line_total)select tenant_id,v_sale,item_id,variant_id,unit_id,stock_location_id,item_kind,description_snapshot,quantity,unit_price,discount_total,line_total from public.erp_service_order_items where tenant_id=p_tenant_id and service_order_id=v_os.id;end if;update public.erp_service_orders set status='completed',subtotal=v_sub,discount_total=v_disc,grand_total=v_total,sale_id=v_sale,completed_at=now(),updated_at=now() where tenant_id=p_tenant_id and id=v_os.id;insert into public.erp_service_order_events(tenant_id,service_order_id,event_type,from_status,to_status,idempotency_key,created_by)values(p_tenant_id,v_os.id,'completed','ready','completed',p_idempotency_key||':event',auth.uid())on conflict(tenant_id,idempotency_key)do nothing;return v_sale;end$$;

do $$declare t text;begin foreach t in array array['erp_assets','erp_asset_identifiers','erp_asset_meter_readings','erp_vehicles','erp_appointments','erp_appointment_resources','erp_service_orders','erp_service_order_items','erp_service_order_events','erp_service_assignments','erp_work_logs','erp_inspections','erp_inspection_items','erp_service_attachments','erp_service_approvals','erp_service_warranties','erp_warranty_events']loop execute format('alter table public.%I enable row level security',t);execute format('create policy %I on public.%I for select to authenticated using ((select erp_security.has_permission(tenant_id,''services.read'')) or (select erp_security.has_permission(tenant_id,''services.manage'')) or (select erp_security.has_permission(tenant_id,''services.execute'')) or (select public.is_platform_staff()))',t||'_select',t);execute format('create policy %I on public.%I for insert to authenticated with check ((select erp_security.has_permission(tenant_id,''services.manage'')) or (select erp_security.has_permission(tenant_id,''services.execute'')) or (select public.is_platform_staff()))',t||'_insert',t);execute format('revoke all on table public.%I from anon,authenticated',t);execute format('grant select,insert on table public.%I to authenticated',t);execute format('grant all on table public.%I to service_role',t);end loop;end$$;
do $$declare t text;begin foreach t in array array['erp_assets','erp_vehicles','erp_appointments','erp_service_orders','erp_service_order_items','erp_inspections','erp_inspection_items','erp_service_approvals','erp_service_warranties']loop execute format('create policy %I on public.%I for update to authenticated using ((select erp_security.has_permission(tenant_id,''services.manage'')) or (select erp_security.has_permission(tenant_id,''services.execute'')) or (select public.is_platform_staff())) with check ((select erp_security.has_permission(tenant_id,''services.manage'')) or (select erp_security.has_permission(tenant_id,''services.execute'')) or (select public.is_platform_staff()))',t||'_update',t);execute format('grant update on table public.%I to authenticated',t);end loop;end$$;
revoke execute on function public.erp_schedule_appointment(uuid,uuid,uuid,uuid,text,timestamptz,timestamptz,text,text,text),public.erp_complete_service_order(uuid,uuid,text) from public,anon;
grant execute on function public.erp_schedule_appointment(uuid,uuid,uuid,uuid,text,timestamptz,timestamptz,text,text,text),public.erp_complete_service_order(uuid,uuid,text) to authenticated,service_role;
commit;
